using App;
using App.Dtos;
using App.Errors;
using ProductModel = App.ApplicationModels.Product;

namespace App.Conversions;

/// <summary>Conversions between the application models and the "products" table: what the service takes and returns.</summary>
public static class ProductConversions
{
    /// <summary>A Product as the products table takes it.</summary>
    public static async Task<ProductCreate> ProductModelToProductCreateAsync(ProductModel model, IUnitOfWork uow)
    {
        var category = await uow.Categories.FindByNameAsync(model.CategoryName)
            ?? throw new NotFoundException("Category", model.CategoryName);
        return new ProductCreate(
            category.Id,
            model.Name,
            model.Price,
            model.Status
        );
    }

    /// <summary>A row of the products table as a Product.</summary>
    public static async Task<ProductModel> ProductReadToProductModelAsync(ProductRead row, IUnitOfWork uow)
    {
        var category = await uow.Categories.FindByIdAsync(row.CategoryId);
        return new ProductModel
        {
            Id = row.Id,
            Name = row.Name,
            Price = row.Price,
            Status = row.Status!,
            CategoryName = category!.Name,
            TagIds = (await uow.ProductTags.ListByProductIdAsync(row.Id)).Select(item => item.TagId).ToList(),
        };
    }
}

