using App;
using App.Common;
using App.Entities;
using App.Errors;
using Microsoft.EntityFrameworkCore;

namespace App.Repositories;

/// <summary>Keeps categories rows in the database, through AppDbContext. A write joins the transaction already open, or is committed at once.</summary>
public class SqlCategoryRepository(AppDbContext db) : ICategoryRepository
{
    public async Task<Category?> FindByIdAsync(int id)
    {
        return await db.Categories.Where(e => e.Id == id).FirstOrDefaultAsync();
    }

    public async Task<Page<Category>> ListAsync(int offset, int limit)
    {
        var query = db.Categories;
        var total = await query.LongCountAsync();
        var items = await query.OrderBy(e => e.Id).Skip(offset).Take(limit).ToListAsync();
        return new Page<Category>(items, total, offset, limit);
    }

    public async Task<Category?> FindByNameAsync(string name)
    {
        return await db.Categories.Where(e => e.Name == name).FirstOrDefaultAsync();
    }

    public async Task<Category> InsertAsync(Category entity)
    {
        db.Categories.Add(entity);
        await SaveAsync();
        return entity;
    }

    public async Task<Category> UpdateAsync(Category entity)
    {
        db.Categories.Update(entity);
        await SaveAsync();
        return entity;
    }

    public async Task DeleteAsync(Category entity)
    {
        db.Categories.Remove(entity);
        await SaveAsync();
    }

    /// <summary>Saves the changes; a database refusal (a unique value, a row still pointed to) becomes a ConflictException.</summary>
    private async Task SaveAsync()
    {
        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateException error)
        {
            db.ChangeTracker.Clear();
            throw new ConflictException("Category", $"the database refused the change: {error.InnerException?.Message ?? error.Message}");
        }
    }
}

