using Microsoft.EntityFrameworkCore;

namespace App.Repositories;

/// <summary>Keeps customers rows in the database, through AppDbContext. A write joins the transaction already open, or is committed at once.</summary>
public class SqlCustomerRepository(AppDbContext db) : ICustomerRepository
{
    public async Task<Customer?> FindByIdAsync(long id)
    {
        return await db.Customers.Where(e => e.Id == id).FirstOrDefaultAsync();
    }

    public async Task<Page<Customer>> ListAsync(int offset, int limit)
    {
        var query = db.Customers;
        var total = await query.LongCountAsync();
        var items = await query.OrderBy(e => e.Id).Skip(offset).Take(limit).ToListAsync();
        return new Page<Customer>(items, total, offset, limit);
    }

    public async Task<Customer?> FindByEmailAsync(string email)
    {
        return await db.Customers.Where(e => e.Email == email).FirstOrDefaultAsync();
    }

    public async Task<Customer> InsertAsync(Customer entity)
    {
        db.Customers.Add(entity);
        await SaveAsync();
        return entity;
    }

    public async Task<Customer> UpdateAsync(Customer entity)
    {
        db.Customers.Update(entity);
        await SaveAsync();
        return entity;
    }

    public async Task DeleteAsync(Customer entity)
    {
        db.Customers.Remove(entity);
        await SaveAsync();
    }

    /// <summary>Saves the changes; a database refusal (a unique value, a row still pointed to) becomes a ConflictException.</summary>
    private async Task SaveAsync()
    {
        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateException error)
        {
            db.ChangeTracker.Clear();
            throw new ConflictException("Customer", $"the database refused the change: {error.InnerException?.Message ?? error.Message}");
        }
    }
}

