using App;
using App.Common;
using App.Dtos;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on categories. Each write runs in its own transaction.</summary>
public class CategoryService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "categories" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Category? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Name");
            if (value is null)
            {
                if (creating || values.ContainsKey("Name")) errors.Add(new FieldError("name", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 60) errors.Add(new FieldError("name", "is longer than 60 characters"));
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Category", errors);
    }

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Category? current)
    {
        {
            var name = values.TryGetValue("Name", out var givenName) ? (string?)givenName : current?.Name;
            if (name is not null)
            {
                var other = await uow.Categories.FindByNameAsync(name);
                if (other is not null && (current is null || !Equals(other.Id, current.Id)))
                    throw new ConflictException("Category", "name is already taken", ["Name"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Category? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Category entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Name", out var name)) entity.Name = (string)name!;
    }

    /// <summary>The Category with this key; NotFoundException when there is none.</summary>
    private static async Task<Category> FindAsync(IUnitOfWork uow, int id) =>
        await uow.Categories.FindByIdAsync(id) ?? throw new NotFoundException("Category", id);

    /// <summary>The Category as services return it.</summary>
    private static CategoryRead Read(Category entity) => new(entity.Id, entity.Name);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(CategoryUpdate changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Name is { IsPresent: true } name) values["Name"] = name.Value;
        return values;
    }

    /// <summary>Stores a new Category after checking it.</summary>
    public async Task<CategoryRead> CreateCategoryAsync(CategoryCreate data)
    {
        var values = new Dictionary<string, object?>();
        if (data.Name is not null) values["Name"] = data.Name;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new Category();
            Apply(entity, values);
            return Read(await uow.Categories.InsertAsync(entity));
        });
    }

    /// <summary>The Category with this key; NotFoundException when there is none.</summary>
    public async Task<CategoryRead> GetCategoryAsync(int id) => Read(await FindAsync(uow, id));

    /// <summary>A page of categories, by primary key.</summary>
    public async Task<Page<CategoryRead>> ListCategoriesAsync(int offset, int limit) => (await uow.Categories.ListAsync(offset, limit)).Map(Read);

    /// <summary>Changes the given values of a Category.</summary>
    public async Task<CategoryRead> UpdateCategoryAsync(int id, CategoryUpdate changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return Read(await uow.Categories.UpdateAsync(current));
        });
    }

    /// <summary>Deletes a Category.</summary>
    public async Task DeleteCategoryAsync(int id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if ((await uow.Products.ListByCategoryIdAsync(current.Id)).Count > 0) throw new ConflictException("Category", "rows of products still point to it", ["products"]);
            await uow.Categories.DeleteAsync(current);
        });
    }

    /// <summary>The Category with this name, or null.</summary>
    public async Task<CategoryRead?> FindCategoryByNameAsync(string name) => await uow.Categories.FindByNameAsync(name) is { } entity ? Read(entity) : null;
}

