        var created = await service.CreateTagAsync(CreateOf(row));
        var found = await service.GetTagAsync(created.Id);
        Assert.Equal(created.Id, found.Id);
    }

    [Fact]
    public async Task RefusesAMissingValue()
    {
        var service = new TagService(uow);
